 findings.append(claim('F4','R5 H3 at layer16: refitted AUROC is '+f"{float(h3[0]['estimate']):.6f}"+' while the unchanged-base readout gives '+f"{float(h3[1]['estimate']):.6f}"+'. A new readout can discriminate labels better than the unchanged original-base function on the same saved representation.',h3,'Descriptive policy comparison only. No policy-gap interval, information-erasure, alignment or rotation claim.'))
