 entry=[plotrow(get('classifier_paired',family.split('_minus_')[0],family.split('_minus_')[1],task,hook,str(sv),policy)) for family,task in TRANS for hook in ANCHORS for policy in POLICIES for sv in SEEDS];profiles=[plotrow(r) for r in rs if r['A09_table_kind']=='classifier_marginal' and r['split']=='dev' and r['task'] in [t for _,t in TRANS] and r['metric']=='auroc'];gaps=[]
