    a=get('classifier_marginal','R5','',task,hook,str(sv),'independent_refit');b=get('classifier_marginal','R5','',task,hook,str(sv),'fixed_original_base');gaps.append({'task':task,'split':'dev','representation':hook,'CV_seed':sv,'metric':'auroc','estimate':float(a['estimate'])-float(b['estimate']),'refitted_row_id':a['A09_row_id'],'fixed_row_id':b['A09_row_id'],'uncertainty':'POINT_ONLY_NO_POLICY_GAP_CI'})
